window.HU_TECH={"sym": "Symmetry and substitution", "tel": "Telescoping", "two": "Counting two ways", "inv": "Invariants", "pig": "Pigeonhole", "mod": "Modular arithmetic", "vie": "Vieta and symmetric functions", "trg": "Trigonometric identities and bounds", "arint": "Integrals as areas or by symmetry", "fint": "Integral reasoning", "root": "Root counting via monotonicity", "ext": "Extremal principle", "col": "Colouring and parity", "game": "Games and losing positions", "log": "Quantifiers, negation and vacuous truth", "prf": "Proof analysis", "ns": "Necessary and sufficient", "ineq": "Inequalities", "circ": "Circle geometry", "ser": "Series and sequences", "poly": "Polynomials", "cnt": "Counting arguments"};
